import { Stream } from '../../../exported-utils/models/stream';
import { debounce } from '../../../exported-utils/throttle';
export class Search {
    constructor() {
        this.userCharacterStream = new Stream();
        this.searchResultsStream = new Stream();
    }
    setSearchResults(results) {
        this.searchResultsStream.fire(results);
    }
    getCharacterStream() {
        return this.userCharacterStream.getReadOnlyStream();
    }
    getDebouncedCharacterStream(timeInMs) {
        if (timeInMs == null) {
            timeInMs = 500;
        }
        const throttledStream = new Stream();
        //Even though we never unsubscribe from this subscription, the objects
        //should get garbage collected when the Search object gets deleted
        //and the throttledStream gets unsubscribed from as well.
        this.userCharacterStream.subscribe(debounce((value) => {
            throttledStream.fire(value);
        }, timeInMs));
        return throttledStream.getReadOnlyStream();
    }
    getSearchResultsStream() {
        return this.searchResultsStream.getReadOnlyStream();
    }
    setSearchText(value) {
        this.userCharacterStream.fire(value);
    }
}
